/*
 * tests/parser.test.js — parser tests against the synthetic fixture.
 *
 * Covers: marker scan, string/int/float decoding, record layout (names,
 * stats, HP float, equipment role, loadout), calibration mapping (current
 * vs base copy, current HP source, rank), robustness (junk prefix, truncated
 * file, non-save file) and the "not a Xenonauts save" error path.
 * All input is generated by tools/fixture-generator.js — never a real save.
 */
(function (root) {
  "use strict";
  const { test } = root.XSTest;
  const XS = root.XS;

  function fixture(seed, soldiers) {
    const { bytes, spec } = XS.fixture.buildFixtureSave({ seed: seed, soldiers: soldiers });
    return { bytes, spec };
  }

  function bufferOf(u8) {
    return u8.buffer.slice(u8.byteOffset, u8.byteOffset + u8.byteLength);
  }

  test("parser: fixture parses, header decoded (save name + in-game date)", (t) => {
    const { bytes, spec } = fixture(42, 10);
    const res = XS.parser.parseSave(bufferOf(bytes));
    t.ok(res.ok, "parse should succeed");
    t.equal(res.header.magic, "onex");
    t.equal(res.header.saveName, spec.header.saveName);
    t.equal(res.header.gameDate, spec.header.gameDate);
    t.equal(res.markerCount, 10);
    t.equal(res.soldiers.length, 10);
  });

  test("parser: marker scan finds every soldier and names decode", (t) => {
    const { bytes, spec } = fixture(7, 12);
    const res = XS.parser.parseSave(bufferOf(bytes));
    t.equal(res.markerCount, 12);
    res.soldiers.forEach((s, i) => {
      t.equal(s.name, spec.soldiers[i].name, "name of soldier " + i);
      t.equal(s.nationality, spec.soldiers[i].nationality);
      t.equal(s.portrait, spec.soldiers[i].portrait);
      t.equal(s.portraitIndex, spec.soldiers[i].portraitIndex);
    });
  });

  test("parser: stat ints decode as 4-byte LE ints, statCount respected", (t) => {
    const { bytes, spec } = fixture(3, 5);
    const res = XS.parser.parseSave(bufferOf(bytes), { statCount: 12 });
    t.equal(res.soldiers[0].statInts.length, 12);
    t.deepEqual(res.soldiers[2].statInts, spec.soldiers[2].statInts);
    // changing the expected stat count changes what is read (settings-driven)
    const res6 = XS.parser.parseSave(bufferOf(bytes), { statCount: 6 });
    t.equal(res6.soldiers[0].statInts.length, 6);
    t.deepEqual(res6.soldiers[0].statInts, spec.soldiers[0].statInts.slice(0, 6));
  });

  test("parser: the float in the padding decodes as 4-byte LE IEEE-754", (t) => {
    const { bytes, spec } = fixture(11, 6);
    const res = XS.parser.parseSave(bufferOf(bytes));
    res.soldiers.forEach((s, i) => {
      t.approx(s.hpFloat, spec.soldiers[i].hpFloat, 1e-4, "hpFloat of soldier " + i);
    });
    t.ok(res.soldiers[0].rawFloats.length >= 1, "raw float list exposed for Calibrate");
  });

  test("parser: anchored strings decode (regiment, experience, role, armour, loadout)", (t) => {
    const { bytes, spec } = fixture(5, 8);
    const res = XS.parser.parseSave(bufferOf(bytes));
    res.soldiers.forEach((s, i) => {
      t.equal(s.strings.regiment, spec.soldiers[i].regiment, "regiment " + i);
      t.equal(s.strings.experience, spec.soldiers[i].experience, "experience " + i);
      t.equal(s.strings.role, spec.soldiers[i].role, "equipment role " + i);
      t.ok(XS.domain.EQUIPMENT_ROLES.indexOf(s.strings.role) !== -1);
      t.ok(s.strings.armour === "armour.basic");
      t.ok(s.strings.loadout.indexOf(spec.soldiers[i].loadout[0]) !== -1, "loadout contains weapon " + i);
      t.ok(s.strings.loadout.indexOf(spec.soldiers[i].loadout[3]) !== -1, "loadout contains grenade " + i);
    });
  });

  test("parser: custom marker string is honored (format is a setting)", (t) => {
    const { bytes } = fixture(9, 4);
    // rename the marker inside the fixture bytes, then scan for the new one
    const marker = new TextEncoder().encode("SoldierFlags");
    const renamed = new TextEncoder().encode("TestFlagXYZ");
    const patched = bytes.slice();
    for (let i = 0; i <= patched.length - marker.length; i++) {
      let eq = true;
      for (let j = 0; j < marker.length; j++) if (patched[i + j] !== marker[j]) { eq = false; break; }
      if (eq) for (let j = 0; j < marker.length; j++) patched[i + j] = renamed[j];
    }
    const res = XS.parser.parseSave(bufferOf(patched), { marker: "TestFlagXYZ" });
    t.ok(res.ok);
    t.equal(res.markerCount, 4);
    const resOld = XS.parser.parseSave(bufferOf(patched), { marker: "SoldierFlags" });
    t.notOk(resOld.ok, "old marker must not be found anymore");
  });

  test("parser: junk before the file does not break the marker scan", (t) => {
    const { bytes, spec } = fixture(13, 6);
    const junk = new Uint8Array(100);
    for (let i = 0; i < junk.length; i++) junk[i] = (i * 37 + 11) & 0xff;
    const combined = new Uint8Array(junk.length + bytes.length);
    combined.set(junk, 0);
    combined.set(bytes, junk.length);
    const res = XS.parser.parseSave(bufferOf(combined));
    t.ok(res.ok);
    t.equal(res.markerCount, 6);
    t.equal(res.soldiers[0].name, spec.soldiers[0].name);
  });

  test("parser: non-save content yields a readable error, not a crash", (t) => {
    const junk = new Uint8Array(2048);
    for (let i = 0; i < junk.length; i++) junk[i] = (i * 91 + 7) & 0xff;
    const res = XS.parser.parseSave(bufferOf(junk));
    t.notOk(res.ok);
    t.ok(/SoldierFlags/.test(res.error), "error should name the marker");
    const tiny = XS.parser.parseSave(bufferOf(new Uint8Array([1, 2, 3])));
    t.notOk(tiny.ok);
  });

  test("parser: truncated file never throws; unreadable blocks are reported", (t) => {
    const { bytes } = fixture(21, 10);
    const cut = Math.floor(bytes.length * 0.6);
    const res = XS.parser.parseSave(bufferOf(bytes.subarray(0, cut)));
    t.ok(res.ok, "markers before the cut are still found");
    t.ok(Array.isArray(res.recordErrors));
    const headerOnly = XS.parser.parseSave(bufferOf(bytes.subarray(0, 120)));
    t.notOk(headerOnly.ok, "header-only slice has no marker");
  });

  // Verified against in-game roster screenshots: the save stores the six
  // stats as slot0=TU, slot1=HP, slot2=STR, slot3=ACC, slot4=RFL, slot5=BRV.
  test("calibration: default mapping matches the verified save order (TU,HP,STR,ACC,RFL,BRV)", (t) => {
    const { bytes, spec } = fixture(31, 6);
    const settings = XS.settings.defaultSettings();
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    t.ok(res.ok);
    t.deepEqual(settings.calibration.statSlots, { TU: 0, HP: 1, STR: 2, ACC: 3, RFL: 4, BRV: 5 });
    res.soldiers.forEach((s, i) => {
      const ints = spec.soldiers[i].statInts;
      t.equal(s.stats.TU, ints[0]);
      t.equal(s.stats.HP, ints[1]);
      t.equal(s.stats.STR, ints[2]);
      t.equal(s.stats.ACC, ints[3]);
      t.equal(s.stats.RFL, ints[4]);
      t.equal(s.stats.BRV, ints[5]);
      t.equal(s.currentHP, null, "currentHP unknown by default: the padding float is NOT current HP (verified on a fresh-game save)");
    });
    // opt-in float mapping still works (hidden Calibrate) for team soldiers
    const sFloat = XS.settings.defaultSettings();
    sFloat.calibration.currentHP = { kind: "float" };
    const resF = XS.parser.parseSaveWithSettings(bufferOf(bytes), sFloat);
    resF.soldiers.forEach((s, i) => t.approx(s.currentHP, spec.soldiers[i].hpFloat, 1e-4, "currentHP from the float when explicitly mapped"));
  });

  test("calibration: switching to the second copy (base) changes the stats", (t) => {
    const { bytes, spec } = fixture(33, 4);
    const settings = XS.settings.defaultSettings();
    settings.calibration.statSlots = { TU: 6, HP: 7, STR: 8, ACC: 9, RFL: 10, BRV: 11 };
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    const ints = spec.soldiers[1].statInts;
    t.equal(res.soldiers[1].stats.TU, ints[6], "TU now comes from slot 6 (base copy)");
    t.equal(res.soldiers[1].stats.HP, ints[7]);
  });

  test("calibration: current HP can come from a slot instead of the float", (t) => {
    const { bytes, spec } = fixture(35, 4);
    const settings = XS.settings.defaultSettings();
    settings.calibration.currentHP = { kind: "slot", slot: 1 };
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    t.equal(res.soldiers[0].currentHP, spec.soldiers[0].statInts[1], "currentHP from HP slot (slot 1)");
  });

  test("calibration: rank maps to postInts[0] (rank points) by default; opting out degrades gracefully", (t) => {
    const { bytes, spec } = fixture(37, 4);
    const settings = XS.settings.defaultSettings();
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    res.soldiers.forEach((s, i) => t.equal(s.rank, spec.soldiers[i].postInts[0], "rank = postInts[0] by default"));
    t.notOk(res.notices.some((n) => /rank/i.test(n)), "no rank notice when mapped");
    res.soldiers.forEach((s) => {
      const frac = XS.domain.hpFraction(s);
      t.ok(frac == null || (frac > 0 && frac <= 1), "hpFraction sane");
    });
    // explicit opt-out: rank 0 and a visible notice, no invented values
    settings.calibration.rank = { kind: "none" };
    const resNone = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    t.ok(resNone.notices.some((n) => /rank/i.test(n)), "rank notice when disabled");
    resNone.soldiers.forEach((s) => t.equal(s.rank, 0));
    // rank from the experience string number
    settings.calibration.rank = { kind: "experience" };
    const res2 = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    t.equal(res2.soldiers[1].rank, 2, "experience.tst2 -> rank 2");
    // rank from an after-stats int (postInt) — exposed raw for calibration
    const fx = XS.fixture.buildFixtureSave({ seed: 39, soldiers: 6 });
    settings.calibration.rank = { kind: "postInt", index: 0 };
    const res3 = XS.parser.parseSaveWithSettings(bufferOf(fx.bytes), settings);
    t.equal(res3.soldiers[2].rank, fx.spec.soldiers[2].postInts[0], "rank from post-stat int #0");
    t.ok(res3.soldiers[0].raw.postInts.length >= 10, "postInts exposed in raw record");
  });

  test("calibration: wound status only when a current-HP mapping is set; default off with a notice", (t) => {
    const { bytes, spec } = fixture(41, 8);
    const settings = XS.settings.defaultSettings();
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    res.soldiers.forEach((s) => t.equal(XS.domain.hpFraction(s), null, "no wound data by default"));
    t.ok(res.notices.some((n) => /wounded check is disabled/.test(n)), "notice explains the wounded check is off");
    res.soldiers.forEach((s, i) => t.equal(s.equipmentRole, spec.soldiers[i].role));
    // with the float mapped explicitly, wound fractions compute (HP is slot 1)
    settings.calibration.currentHP = { kind: "float" };
    const res2 = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    res2.soldiers.forEach((s, i) => {
      t.approx(XS.domain.hpFraction(s), spec.soldiers[i].hpFloat / spec.soldiers[i].statInts[1], 1e-6);
    });
  });

  test("calibration: PVT->CPL promotion bonus (+2 to every stat) applied from rank points, matching the in-game screen", (t) => {
    // Verified against a fresh-game save + roster screenshot: screen = save
    // stat int + 2 for soldiers with rank points >= 3; the ints do NOT include it
    const { bytes, spec } = XS.fixture.buildFixtureSave({ seed: 51, soldiers: 4, rankPoints: 5 }); // CPL tier
    const settings = XS.settings.defaultSettings();
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    res.soldiers.forEach((s, i) => {
      const ints = spec.soldiers[i].statInts;
      for (const st of XS.domain.STATS) {
        t.equal(s.stats[st], ints[settings.calibration.statSlots[st]] + 2, st + " includes the +2 promotion bonus");
      }
      t.equal(s.rank, 5, "rank points read from postInts[0]");
      t.equal(XS.domain.rankLabel(s.rank), "CPL", "rank label");
    });
    // PVT (0 points): no bonus, raw ints
    const fx0 = XS.fixture.buildFixtureSave({ seed: 52, soldiers: 3 });
    const res0 = XS.parser.parseSaveWithSettings(bufferOf(fx0.bytes), settings);
    res0.soldiers.forEach((s, i) => {
      for (const st of XS.domain.STATS) {
        t.equal(s.stats[st], fx0.spec.soldiers[i].statInts[settings.calibration.statSlots[st]], "PVT: raw int, no bonus");
      }
      t.equal(s.rank, 0);
      t.equal(XS.domain.rankLabel(s.rank), "PVT");
    });
    // bonus tunable off via settings
    const s2 = XS.settings.defaultSettings();
    s2.calibration.promotionBonus = { rankPointsAtOrAbove: 3, bonus: 0 };
    const res2 = XS.parser.parseSaveWithSettings(bufferOf(bytes), s2);
    t.equal(res2.soldiers[0].stats.TU, spec.soldiers[0].statInts[0], "bonus 0 disables it");
  });

  test("parser: current-HP float is read at the configured offset (stats-end + hpFloatOffset)", (t) => {
    const { bytes, spec } = fixture(43, 5);
    const res = XS.parser.parseSave(bufferOf(bytes), { hpFloatOffset: 40 });
    res.soldiers.forEach((s, i) => t.approx(s.hpFloat, spec.soldiers[i].hpFloat, 1e-4, "hpFloat soldier " + i));
    // a wrong offset falls back to the scan window and still finds the float
    const res2 = XS.parser.parseSave(bufferOf(bytes), { hpFloatOffset: 8 });
    t.approx(res2.soldiers[0].hpFloat, spec.soldiers[0].hpFloat, 1e-4, "fallback scan finds the float");
  });

  test("parser: team membership — weapon.* presence marks active team, recruits have armour only", (t) => {
    const { bytes, spec } = XS.fixture.buildFixtureSave({ seed: 44, soldiers: 9, recruitEvery: 3 });
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), XS.settings.defaultSettings());
    t.equal(res.soldiers.length, 9);
    res.soldiers.forEach((s, i) => {
      t.equal(s.inTeam, spec.soldiers[i].inTeam, "inTeam of soldier " + i);
      t.equal(s.inTeam, s.loadout.length > 0, "in-team <=> has weapon/ammo loadout");
    });
    t.equal(res.soldiers.filter((s) => s.inTeam).length, 6);
    t.equal(res.soldiers.filter((s) => !s.inTeam).length, 3);
  });

  test("parser: recruit blocks — the HP-offset float is NOT current HP (recruits are full HP in-game)", (t) => {
    // Verified against the in-game recruit screen AND a fresh-game save: the
    // float at hpFloatOffset is a different field (fresh team soldiers are at
    // full HP in-game while the float reads 22-35). Default: no wound data at
    // all. Even with the float mapped explicitly, recruits are never wounded.
    const { bytes, spec } = XS.fixture.buildFixtureSave({ seed: 45, soldiers: 6, recruitEvery: 2 });
    const settings = XS.settings.defaultSettings();
    const res = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    res.soldiers.forEach((s) => t.equal(s.currentHP, null, "current HP unknown by default for everyone"));
    t.ok(res.notices.some((n) => /wounded check is disabled/.test(n)));
    // float mapping enabled: team soldiers get the float, recruits stay null
    settings.calibration.currentHP = { kind: "float" };
    const res2 = XS.parser.parseSaveWithSettings(bufferOf(bytes), settings);
    res2.soldiers.forEach((s, i) => {
      if (spec.soldiers[i].inTeam) t.approx(s.currentHP, spec.soldiers[i].hpFloat, 1e-4, "team soldier " + i + " gets the mapped float");
      else t.equal(s.currentHP, null, "recruit " + i + ": never wounded (full HP in-game)");
    });
    t.ok(res2.notices.some((n) => /full HP/.test(n)), "notice explains the recruit HP handling");
  });

  test("parser: teamStringPrefix is a setting — empty prefix disables the distinction", (t) => {
    const { bytes } = XS.fixture.buildFixtureSave({ seed: 45, soldiers: 6, recruitEvery: 2 });
    const res = XS.parser.parseSave(bufferOf(bytes), { teamStringPrefix: "" });
    t.ok(res.soldiers.every((s) => s.inTeam), "empty prefix -> everyone in team");
    const res2 = XS.parser.parseSave(bufferOf(bytes), { teamStringPrefix: "armour." });
    t.ok(res2.soldiers.every((s) => s.inTeam), "armour. prefix -> everyone has armour -> all in team");
    const res3 = XS.parser.parseSave(bufferOf(bytes), { teamStringPrefix: "weapon." });
    t.equal(res3.soldiers.filter((s) => s.inTeam).length, 3, "weapon. prefix -> only equipped soldiers");
  });
})(typeof self !== "undefined" ? self : globalThis);
